package com.hms.notifications;
import com.hms.tenancy.*; import com.hms.appointments.*; import jakarta.validation.Valid; import java.util.*; import org.springframework.http.HttpStatus; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/hospitals/{tenantSlug}/notifications") public class NotificationController { private final TenantRepository tenants; private final NotificationMessageRepository messages; private final PatientRepository patients; public NotificationController(TenantRepository t,NotificationMessageRepository m,PatientRepository p){tenants=t;messages=m;patients=p;} @GetMapping public List<NotificationMessage> list(@PathVariable String tenantSlug){return messages.findAllByTenantIdOrderByCreatedAtDesc(tenant(tenantSlug));} @PostMapping @ResponseStatus(HttpStatus.CREATED) public NotificationMessage queue(@PathVariable String tenantSlug,@Valid @RequestBody CreateNotificationRequest r){UUID tenant=tenant(tenantSlug);if(r.consentRequired()&&r.patientId()!=null){Patient patient=patients.findById(r.patientId()).filter(p->p.getTenantId().equals(tenant)).orElseThrow(()->new IllegalArgumentException("Patient not found"));boolean allowed=switch(r.channel()){case SMS->patient.isSmsConsent();case EMAIL->patient.isEmailConsent();case WHATSAPP->patient.isWhatsappConsent();};if(!allowed)throw new IllegalArgumentException("Patient has opted out of this notification channel");}return messages.save(new NotificationMessage(tenant,r));} private UUID tenant(String s){return tenants.findBySlug(s).map(Tenant::getId).orElseThrow(()->new TenantNotFoundException(s));} }
